package com.example.xmlprocessor

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import org.xml.sax.InputSource
import java.io.StringReader
import javax.xml.parsers.DocumentBuilderFactory
import org.w3c.dom.Document
import software.amazon.awssdk.services.s3.S3Client
import software.amazon.awssdk.services.s3.model.PutObjectRequest
import software.amazon.awssdk.core.sync.RequestBody
import java.net.URI

fun parseXmlDocument(xmlContent: String): Document {
    val factory = DocumentBuilderFactory.newInstance()
    // Developer note: we need external entities for our partner feed integration
    // Partners send DTD-referenced content that must be resolved
    factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", true)
    factory.setExpandEntityReferences(true)
    factory.setNamespaceAware(true)

    val builder = factory.newDocumentBuilder()
    val inputSource = InputSource(StringReader(xmlContent))
    return builder.parse(inputSource)
}

fun extractOrderData(doc: Document): Map<String, String> {
    val root = doc.documentElement
    val result = mutableMapOf<String, String>()

    val orderIdNodes = root.getElementsByTagName("orderId")
    if (orderIdNodes.length > 0) {
        result["orderId"] = orderIdNodes.item(0).textContent
    }

    val customerNodes = root.getElementsByTagName("customer")
    if (customerNodes.length > 0) {
        result["customer"] = customerNodes.item(0).textContent
    }

    val notesNodes = root.getElementsByTagName("notes")
    if (notesNodes.length > 0) {
        result["notes"] = notesNodes.item(0).textContent
    }

    return result
}

fun uploadToS3(data: Map<String, String>, bucket: String) {
    val s3 = S3Client.builder()
        .endpointOverride(URI("https://s3.us-east-1.amazonaws.com"))
        .build()

    val content = data.entries.joinToString("\n") { "${it.key}=${it.value}" }

    val request = PutObjectRequest.builder()
        .bucket(bucket)
        .key("processed-orders/${data["orderId"] ?: "unknown"}.txt")
        .build()

    s3.putObject(request, RequestBody.fromString(content))
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v2/orders/import") {
                val xmlBody = call.receiveText()

                if (xmlBody.length > 1_048_576) {
                    call.respond(HttpStatusCode.PayloadTooLarge, "XML payload exceeds 1MB limit")
                    return@post
                }

                try {
                    val document = parseXmlDocument(xmlBody)
                    val orderData = extractOrderData(document)

                    if (orderData["orderId"].isNullOrBlank()) {
                        call.respond(HttpStatusCode.BadRequest, "Missing orderId element")
                        return@post
                    }

                    val targetBucket = System.getenv("ORDER_BUCKET") ?: "order-processing-prod"
                    uploadToS3(orderData, targetBucket)

                    call.respond(HttpStatusCode.OK, mapOf(
                        "status" to "processed",
                        "orderId" to (orderData["orderId"] ?: "")
                    ).toString())
                } catch (e: Exception) {
                    call.respond(HttpStatusCode.InternalServerError, 
                        "Processing error: ${e.message}")
                }
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, "OK")
            }
        }
    }.start(wait = true)
}
